// src/components/ROI/ProjectLeadROIEntry.js
import React, { useEffect, useState } from "react";
import axios from "axios";
import {
  useParams,
  NavLink,
  Outlet,
  useLocation,
  useNavigate,
} from "react-router-dom";
import "./roiTabs.css";

export default function ProjectLeadROIEntry() {
  const { intakeNumber } = useParams();
  const location = useLocation();
  const navigate = useNavigate();

  // Keep your existing row-driven UI pattern — first row carries the header fields
  const [rows, setRows] = useState([
    {
      Release: "",
      ROIMonth: "",
      ProjectName: "",
      AutomationLead: "",
      // (keep any other original fields here, unchanged)
      SavingsCategory: "",
      AutomationFmk: "",
      TotalTCsCount: "",
      ManualTCsPD: "",
      AutomatedTCCreatedPD: "",
      NumberofCycles: "",
      TotalManualPD: 0,
      TotalManualCost: 0,
      TotalAutomatedPD: 0,
      TotalAutomationCost: 0,
      Savings: 0,
    },
  ]);

  const [projectDetails, setProjectDetails] = useState(null);
  const [popupText, setPopupText] = useState("");

  const handleChange = (index, field, value) => {
    setRows((prev) => {
      const copy = [...prev];
      copy[index] = { ...copy[index], [field]: value };
      return copy;
    });
  };

  // Define deleteRow *inside* the component so it can access rows/setRows
  const deleteRow = (index) => {
    setRows((prev) => {
      const copy = [...prev];
      copy.splice(index, 1);
      return copy;
    });
  };

  // Fetch project details and prefill header fields
  useEffect(() => {
    if (!intakeNumber) return;
    axios
      .get(`http://localhost:5000/api/projects/${intakeNumber}`)
      .then((res) => {
        setProjectDetails(res.data);

        const currentMonth = new Date().toLocaleString("default", {
          month: "long",
          year: "numeric",
        }); // e.g., "September 2025"

        setRows((prev) =>
          prev.map((row) => ({
            ...row,
            ProjectName: res.data?.intake_name || "",
            AutomationLead: res.data?.automation_qe_lead || "",
            Release: res.data?.release || row.Release,
            ROIMonth: currentMonth || row.ROIMonth,
          }))
        );
      })
      .catch((err) => {
        console.error("Error fetching project details", err);
      });
  }, [intakeNumber]);

  // If user lands on the parent path, redirect into the default "summary" tab
  useEffect(() => {
    const base = `/ROI/ProjectLeadROIEntry/${intakeNumber}`;
    const isOnBase =
      location.pathname === base || location.pathname === `${base}/`;
    if (intakeNumber && isOnBase) {
      navigate("summary", { replace: true });
    }
  }, [location.pathname, intakeNumber, navigate]);

  return (
    <div className="p-4">
      <h2 className="text-xl font-semibold mb-4">
        Project Lead ROI Entry — Intake #{intakeNumber}
      </h2>

      {/* Tabs */}
      <div className="roi-tabs">
        <NavLink className="roi-tab" to={`summary`}>
          Summary
        </NavLink>
        <NavLink className="roi-tab" to={`project-savings`}>
          Project Savings
        </NavLink>
        <NavLink className="roi-tab" to={`initiative-savings`}>
          Initiative Savings
        </NavLink>
        <NavLink className="roi-tab" to={`soa-savings`}>
          SOA Savings
        </NavLink>
        <NavLink className="roi-tab" to={`monthly-breakup`}>
          Monthly Breakup
        </NavLink>
      </div>

      {/* Tab content */}
      <div className="roi-tab-panel">
        <Outlet context={{ intakeNumber, projectDetails, rows, setRows }} />
      </div>

      {/* Header form (visible, uneditable where required) */}
      <div className="space-y-4 mb-6 mt-6">
        <h3 className="text-lg font-semibold text-gray-700">Project Details</h3>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Release:</label>
          <input
            type="text"
            value={rows[0]?.Release || ""}
            onChange={() => {}}
            disabled
            className="flex-1 border rounded-md px-3 py-2 bg-gray-100"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">ROI Month:</label>
          <input
            type="text"
            value={rows[0]?.ROIMonth || ""}
            onChange={(e) => handleChange(0, "ROIMonth", e.target.value)}
            className="flex-1 border rounded-md px-3 py-2"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Project Name:</label>
          <input
            type="text"
            value={rows[0]?.ProjectName || ""}
            disabled
            className="flex-1 border rounded-md px-3 py-2 bg-gray-100"
          />
        </div>

        <div className="flex items-center gap-2">
          <label className="w-40 text-gray-600">Automation Lead:</label>
          <input
            type="text"
            value={rows[0]?.AutomationLead || ""}
            disabled
            className="flex-1 border rounded-md px-3 py-2 bg-gray-100"
          />
        </div>
      </div>

      {/* Keep your existing rows/edit/save UI here (if any).
          Example minimal skeleton below; adjust to your original controls. */}
      <div className="mt-6">
        <h3 className="text-lg font-semibold text-gray-700 mb-2">ROI Rows</h3>
        {rows.map((row, idx) => (
          <div key={idx} className="relative p-3 border rounded mb-2">
            <div className="text-sm text-gray-500 mb-2">Row {idx + 1}</div>
            {/* ... your per-row controls here ... */}
            {idx > 0 && (
              <button
                className="absolute top-2 right-2 text-red-500 hover:text-red-700 font-bold"
                onClick={() => deleteRow(idx)}
                title="Delete Row"
              >
                ✕
              </button>
            )}
          </div>
        ))}
      </div>
    </div>
  );
}
